    job_set(KEY, None, 'GNSSFIX3_UNDO')
    if os.path.exists(R+SOFF) and (rec.get('gnssstep_gate_moved') or not rec):
        if not os.path.exists(R+SGATE): os.rename(R+SOFF, R+SGATE); print('GNSSFIX3_UNDO gnssstep gate restored')
        else: os.remove(R+SOFF)
    for p in (GATE, BIN):
